<?php
header('Content-Type: application/json');require_once __DIR__.'/../config/response.php';require_once __DIR__.'/../config/db.php';require_once __DIR__.'/../auth/auth_required.php';require_once __DIR__.'/../auth/role_helper.php';require_once __DIR__.'/report_error.php';
try{$userId=(int)requireAuth()->id;$conn=db();requirePermission($conn,$userId,'reports.view');$stmt=$conn->prepare('SELECT id,period_start,period_end,opening_credit,vat_collected,vat_deductible,ROUND(opening_credit+vat_deductible,3) available_credit,vat_payable,closing_credit,status,source_period_id,reviewed_by,reviewed_at,locked_by,locked_at,filed_by,filed_at,created_at,updated_at FROM erp_vat_periods WHERE user_id=? ORDER BY period_start DESC');$stmt->bind_param('i',$userId);$stmt->execute();$rows=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);$stmt->close();jsonResponse(['success'=>true,'formula'=>'payable=max(collected-opening-deductible,0); closing=max(opening+deductible-collected,0)','data'=>$rows]);}catch(Throwable $e){reportFailureResponse($e,'Could not load the VAT periods.','VAT_PERIOD_LOAD_FAILED');}
